import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CBWbbCW8.js";const p=JSON.parse('{"title":"Hermes / OpenClaw 403 代理","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/hermes-openclaw-403.md","filePath":"integrations/hermes-openclaw-403.md","lastUpdated":null}'),r={name:"integrations/hermes-openclaw-403.md"};function o(d,e,n,s,h,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="hermes-openclaw-403-代理" tabindex="-1">Hermes / OpenClaw 403 代理 <a class="header-anchor" href="#hermes-openclaw-403-代理" aria-label="Permalink to &quot;Hermes / OpenClaw 403 代理&quot;">​</a></h1><p>部分工具调用模型时可能遇到 403，常见原因是请求格式、目标接口或权限策略不匹配。Hermes / OpenClaw 这类代理层通常用于处理格式转换、请求转发或特定客户端兼容问题。</p><h2 id="什么时候需要代理" tabindex="-1">什么时候需要代理 <a class="header-anchor" href="#什么时候需要代理" aria-label="Permalink to &quot;什么时候需要代理&quot;">​</a></h2><ul><li>工具只支持某一种固定供应商格式，无法直接配置 OpenAI Compatible。</li><li>工具固定请求某个接口路径，不能改成 <code>https://doudi.ai/v1</code>。</li><li>客户端侧存在 403，但用 curl 直接请求 DouDi.ai 可以成功。</li><li>需要把 Anthropic 风格请求转换为 OpenAI 兼容请求。</li></ul><h2 id="推荐排查顺序" tabindex="-1">推荐排查顺序 <a class="header-anchor" href="#推荐排查顺序" aria-label="Permalink to &quot;推荐排查顺序&quot;">​</a></h2><ol><li>先用 curl 直接请求 DouDi.ai，确认 API Key、模型和余额正常。</li><li>再检查客户端请求的 Base URL 是否正确。</li><li>如果直连成功、客户端失败，再考虑代理层。</li><li>在代理日志中查看实际转发到 DouDi.ai 的 URL、Header 和模型名。</li></ol><h2 id="代理配置要点" tabindex="-1">代理配置要点 <a class="header-anchor" href="#代理配置要点" aria-label="Permalink to &quot;代理配置要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>建议</th></tr></thead><tbody><tr><td>上游地址</td><td><code>https://doudi.ai/v1</code></td></tr><tr><td>上游 Key</td><td>DouDi.ai API Key</td></tr><tr><td>模型映射</td><td>把客户端模型名映射到 DouDi.ai 可用模型</td></tr><tr><td>Header</td><td>保留 <code>Authorization: Bearer YOUR_API_KEY</code></td></tr></tbody></table><h2 id="_403-常见原因" tabindex="-1">403 常见原因 <a class="header-anchor" href="#_403-常见原因" aria-label="Permalink to &quot;403 常见原因&quot;">​</a></h2><ul><li>API Key 无权限或已禁用。</li><li>模型不在当前账号分组中。</li><li>客户端请求了 DouDi.ai 不支持的接口格式。</li><li>代理层把 Header 或路径改坏了。</li><li>工具侧默认启用了不兼容的供应商协议。</li></ul>',10)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
